/* eslint-disable */
var addSorting = (function() {
    'use strict';
    var cols,
        currentSort = {
            index: 0,
            desc: false
        };

    // returns the summary table element
    function getTable() {
        return document.querySelector('.coverage-summary');
    }
    // returns the thead element of the summary table
    function getTableHeader() {
        return getTable().querySelector('thead tr');
    }
    // returns the tbody element of the summary table
    function getTableBody() {
        return getTable().querySelector('tbody');
    }
    // returns the th element for nth column
    function getNthColumn(n) {
        return getTableHeader().querySelectorAll('th')[n];
    }

    function onFilterInput() {
        const searchValue = document.getElementById('fileSearch').value;
        const rows = document.getElementsByTagName('tbody')[0].children;
        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            if (
                row.textContent
                    .toLowerCase()
                    .includes(searchValue.toLowerCase())
            ) {
                row.style.display = '';
            } else {
                row.style.display = 'none';
            }
        }
    }

    // loads the search box
    function addSearchBox() {
        var template = document.getElementById('filterTemplate');
        var templateClone = template.content.cloneNode(true);
        templateClone.getElementById('fileSearch').oninput = onFilterInput;
        template.parentElement.appendChild(templateClone);
    }

    // loads all columns
    function loadColumns() {
        var colNodes = getTableHeader().querySelectorAll('th'),
            colNode,
            cols = [],
            col,
            i;

        for (i = 0; i < colNodes.length; i += 1) {
            colNode = colNodes[i];
            col = {
                key: colNode.getAttribute('data-col'),
                sortable: !colNode.getAttribute('data-nosort'),
                type: colNode.getAttribute('data-type') || 'string'
            };
            cols.push(col);
            if (col.sortable) {
                col.defaultDescSort = col.type === 'number';
                colNode.innerHTML =
                    colNode.innerHTML + '<span class="sorter"></span>';
            }
        }
        return cols;
    }
    // attaches a data attribute to every tr element with an object
    // of data values keyed by column name
    function loadRowData(tableRow) {
        var tableCols = tableRow.querySelectorAll('td'),
            colNode,
            col,
            data = {},
            i,
            val;
        for (i = 0; i < tableCols.length; i += 1) {
            colNode = tableCols[i];
            col = cols[i];
            val = colNode.getAttribute('data-value');
            if (col.type === 'number') {
                val = Number(val);
            }
            data[col.key] = val;
        }
        return data;
    }
    // loads all row data
    function loadData() {
        var rows = getTableBody().querySelectorAll('tr'),
            i;

        for (i = 0; i < rows.length; i += 1) {
            rows[i].data = loadRowData(rows[i]);
        }
    }
    // sorts the table using the data for the ith column
    function sortByIndex(index, desc) {
        var key = cols[index].key,
            sorter = function(a, b) {
                a = a.data[key];
                b = b.data[key];
                return a < b ? -1 : a > b ? 1 : 0;
            },
            finalSorter = sorter,
            tableBody = document.querySelector('.coverage-summary tbody'),
            rowNodes = tableBody.querySelectorAll('tr'),
            rows = [],
            i;

        if (desc) {
            finalSorter = function(a, b) {
                return -1 * sorter(a, b);
            };
        }

        for (i = 0; i < rowNodes.length; i += 1) {
            rows.push(rowNodes[i]);
            tableBody.removeChild(rowNodes[i]);
        }

        rows.sort(finalSorter);

        for (i = 0; i < rows.length; i += 1) {
            tableBody.appendChild(rows[i]);
        }
    }
    // removes sort indicators for current column being sorted
    function removeSortIndicators() {
        var col = getNthColumn(currentSort.index),
            cls = col.className;

        cls = cls.replace(/ sorted$/, '').replace(/ sorted-desc$/, '');
        col.className = cls;
    }
    // adds sort indicators for current column being sorted
    function addSortIndicators() {
        getNthColumn(currentSort.index).className += currentSort.desc
            ? ' sorted-desc'
            : ' sorted';
    }
    // adds event listeners for all sorter widgets
    function enableUI() {
        var i,
            el,
            ithSorter = function ithSorter(i) {
                var col = cols[i];

                return function() {
                    var desc = col.defaultDescSort;

                    if (currentSort.index === i) {
                        desc = !currentSort.desc;
                    }
                    sortByIndex(i, desc);
                    removeSortIndicators();
                    currentSort.index = i;
                    currentSort.desc = desc;
                    addSortIndicators();
                };
            };
        for (i = 0; i < cols.length; i += 1) {
            if (cols[i].sortable) {
                // add the click event handler on the th so users
                // dont have to click on those tiny arrows
                el = getNthColumn(i).querySelector('.sorter').parentElement;
                if (el.addEventListener) {
                    el.addEventListener('click', ithSorter(i));
                } else {
                    el.attachEvent('onclick', ithSorter(i));
                }
            }
        }
    }
    // adds sorting functionality to the UI
    return function() {
        if (!getTable()) {
            return;
        }
        cols = loadColumns();
        loadData();
        addSearchBox();
        addSortIndicators();
        enableUI();
    };
})();

window.addEventListener('load', addSorting);

import AsyncStorage from "@react-native-async-storage/async-storage";
import { GoogleSignin } from "@react-native-google-signin/google-signin";
import { NavigationContainerRef } from "@react-navigation/native";
import axios from "axios";
import { Alert } from "react-native";
import { useStringsAndLabels } from "~/app-hooks/use-strings-and-labels";
import { animationDuration } from "~/assets/constants";
import { navigations } from "~/config/app-navigation/constant";
import { getNavigator } from "~/config/app-navigation/root-navigation";
import { API } from "~/network/api";
import { persistKeys } from "~/network/constant";
import { clearReducer } from "~/network/reducers/logout-reducer";
import { store } from "~/network/reducers/store";
import { queryClient } from "../app";

export const logoutUser = async (navigation: NavigationContainerRef<any>) => {
  console.log("logoutUser");
  navigation.reset({ index: 0, routes: [{ name: navigations.LOGIN }] });

  store.dispatch(clearReducer());
  await AsyncStorage.multiRemove([
    persistKeys.token,
    persistKeys.fcmToken,
    persistKeys.userProfileId,
    persistKeys.userProfilePic,
  ]);
  setTimeout(() => {
    queryClient.getQueryCache().clear();
  }, animationDuration.D2000);

  axios.defaults.headers.common.Authorization = "";
  API.initService();

  try {
    await GoogleSignin.revokeAccess();
    await GoogleSignin.signOut();
    // this.setState({ user: null }); // Remember to remove the user from your app's state as well
  } catch (error) {
    console.error(error);
  }
};

export function useLogout() {
  const { strings } = useStringsAndLabels();
  const navigationRef = getNavigator();

  const onLogout = async (force: boolean | undefined = false) => {
    if (force) {
      await logoutUser(navigationRef);
      return;
    }
    Alert.alert(
      strings.logout,
      strings.areYouLogout,
      [
        { text: strings.no, onPress: () => null, style: "cancel" },
        {
          text: strings.yes,
          onPress: () => {
            logoutUser(navigationRef);
          },
        },
      ],
      { cancelable: false }
    );
  };

  return { onLogout };
}

import { API } from "~/network/api";
import { persistKeys } from "~/network/constant";
import AsyncStorage from "@react-native-async-storage/async-storage";
import axios from "axios";
import { useEffect, useState } from "react";

export const onSetToken = async (value: string) => {
  axios.defaults.headers.common.Authorization = `Bearer ${value}`;
  API.initService();

  await AsyncStorage.setItem(persistKeys.token, value);
};

export const useToken = () => {
  const [token, setToken] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkToken = async () => {
      const tok = (await AsyncStorage.getItem(persistKeys.token)) ?? "";
      setToken(tok);
      setLoading(false);
    };

    checkToken();
  }, []);

  return { token, loading, onSetToken };
};

import notifee, { EventType, Notification } from "@notifee/react-native";
import { ParamListBase, useNavigation } from "@react-navigation/native";
import { StackNavigationProp } from "@react-navigation/stack";
import _ from "lodash/fp";
import { useCallback, useEffect } from "react";
import { useNotificationService } from "~/navigation/NotificationService";
import { Screens } from "~/navigation/types";
import { ChapterData } from "~/types/chapter";
import { Group } from "~/types/group";
import { LocalEvent } from "~/types/local-event";
import { OneUser, OneUserData } from "~/types/one-user";
import { Post } from "~/types/post";

export function useNavigations() {
  const navigation = useNavigation<StackNavigationProp<ParamListBase>>();
  const { pullNotifications } = useNotificationService();

  const gotoPostDetails = useCallback(
    (post: string | Post, reply?: string, isReplyFocus?: boolean) => () => {
      navigation.navigate(Screens.POST_DETAIL, {
        id: asId(post),
        reply: reply,
        isReplyFocus,
      });
    },
    [navigation]
  );

  const gotoGroupDetails = useCallback(
    (group: string | Group) => () => {
      navigation.push(Screens.GROUP_DETAIL, {
        id: asId(group),
      });
    },
    [navigation]
  );

  // Subscribe to events
  useEffect(() => {
    const handleNotificationPress = (notification: Notification) => {
      const data = notification?.data;
      if (data && !_.isEmpty(data)) {
        const post = data["post"] as string;
        const parent = data["parent"] as string;
        console.log("post", post);
        console.log("parent", parent);
        gotoPostDetails(post)();
      } else {
        const receivedNotifications = pullNotifications();
        console.log("navigatingTo", receivedNotifications);
        if (receivedNotifications.length > 0) {
          gotoPostDetails(receivedNotifications[0].post)();
        }
      }
    };

    return notifee.onForegroundEvent(({ type, detail }) => {
      const { notification } = detail;
      console.log("onForegroundEvent", notification);

      switch (type) {
        case EventType.DISMISSED:
          console.log("User dismissed notification", notification);
          break;
        case EventType.PRESS:
          console.log("User pressed notification", notification);
          if (notification) {
            handleNotificationPress(notification);
          }
          break;
        case EventType.DELIVERED:
          console.log("Received notification", notification);
          // Ignore notifications which are simply delivered
          break;
        default:
          console.log("Unknown action " + type, notification);
      }
      if (notification?.id) {
        // console.log("canceling notification");
        // notifee
        //   .cancelDisplayedNotification(notification.id)
        //   .catch((e) => LOG.error("Error canceling displayed notification", e));
        // notifee
        //   .cancelNotification(notification.id)
        //   .catch((e) => LOG.error("Error canceling notification", e));
      }
    });
  }, []);

  const asId = (v: string | OneUser | Post | LocalEvent | Group) =>
    _.isString(v) ? v : v?.id;

  const gotoUserProfile = (user: string | OneUser) => () => {
    navigation.navigate(Screens.USER_PROFILE, {
      id: asId(user),
    });
  };

  const gotoMyProfile = () => {
    navigation.navigate(Screens.MY_PROFILE);
  };

  const gotoEventDetails =
    (event: string | LocalEvent, reply?: string) => () => {
      navigation.navigate(Screens.EVENT_DETAIL, {
        id: asId(event),
        reply: reply,
      });
    };

  const showPostContextMenu = (post: string | Post, author: string) => () => {
    navigation.navigate(Screens.POST_CONTEXT_MENU_MODAL, {
      postId: asId(post),
      authorId: author,
    });
  };

  interface GiveGratisProps {
    post: string | Post;
    commentId?: string;
    replyId?: string;
  }
  const showGiveGratisModal =
    ({ post, commentId, replyId }: GiveGratisProps) =>
    () => {
      navigation.navigate(Screens.GIVE_GRATIS_MODAL, {
        postId: asId(post),
        commentId,
        replyId,
      });
    };

  const gotoCreatePost = ({ groupId }: { groupId?: string }) => {
    navigation.navigate(Screens.CREATE_POST, { groupId });
  };

  const gotoCreateEvent = ({ groupId }: { groupId?: string }) => {
    navigation.navigate(Screens.CREATE_EVENT, { groupId });
  };

  const gotoCreateGroup = ({ parentId }: { parentId?: string }) => {
    navigation.navigate(Screens.CREATE_GROUP, { parentId });
  };

  const gotoEditGroup = (id: string) => {
    navigation.navigate(Screens.EDIT_GROUP, {
      id,
    });
  };

  interface ChooseUsersProps {
    type: string;
    users: OneUserData[];
  }
  const gotoChooseUsers = ({ type, users }: ChooseUsersProps) => {
    navigation.navigate(Screens.SELECT_USERS, {
      type,
      users,
    });
  };

  interface ChooseChaptersProps {
    chapters: ChapterData[];
  }
  const gotoChooseChapters = ({ chapters }: ChooseChaptersProps) => {
    navigation.navigate(Screens.SELECT_CHAPTERS, {
      chapters,
    });
  };

  return {
    gotoUserProfile,
    gotoMyProfile,
    gotoPostDetails,
    gotoEventDetails,
    gotoGroupDetails,
    showPostContextMenu,
    showGiveGratisModal,
    gotoCreatePost,
    gotoCreateEvent,
    gotoCreateGroup,
    gotoEditGroup,
    gotoChooseUsers,
    gotoChooseChapters,
  };
}

import { forwardRef, useImperativeHandle, useState } from "react";
import { Calendar } from "react-native-calendars";

interface CalenderComponentProps {}

export type CalenderRefProps = {
  onOpenModal: () => void;
  onCloseModal: () => void;
};

export const CalenderComponent = (
  props: CalenderComponentProps,
  ref: React.Ref<unknown> | undefined
) => {
  const {} = props || {};
  const [selected, setSelected] = useState("");
  const [startDate, setStartDate] = useState(new Date());
  const [endDate, setEndDate] = useState(new Date());
  const [showPicker, setShowPicker] = useState(false);
  const [pickerType, setPickerType] = useState("");

  useImperativeHandle(ref, () => ({
    onOpenModal(type: "start" | "end") {
      if (type === "start") {
        showStartDatePicker();
        return;
      }
      showEndDatePicker();
    },
    onCloseModal() {
      showEndDatePicker();
    },
  }));

  const showStartDatePicker = () => {
    setShowPicker(true);
    setPickerType("start");
  };

  const showEndDatePicker = () => {
    setShowPicker(true);
    setPickerType("end");
  };

  return (
    <Calendar
      ref={ref}
      onDayPress={(day) => {
        setSelected(day.dateString);
      }}
      markedDates={{
        [selected]: {
          selected: true,
          disableTouchEvent: true,
          //   selectedDotColor: 'orange',
        },
      }}
    />
  );
};

export const CalenderComponentModal = forwardRef(CalenderComponent);

