interface InputProps extends TextInputProps {
  inputStyle?: StyleProp<ViewStyle>;
  isError?: boolean;
  hasMobile?: boolean;
  errorMsg?: string;
  children?: React.ReactNode;
  height?: number;
  placeholder?: string;
  onFocus?: (e: any) => void;
}

export const Input = (props: InputProps) => {
  const { theme } = useAppTheme();
  const styles = createStyleSheet(theme);

  const {
    inputStyle,
    isError = false,
    hasMobile = false,
    errorMsg = "",
    children,
    height = verticalScale(52),
    ...remainingProps
  } = props || {};

  let mobileProps = {};
  if (hasMobile) {
    mobileProps = {
      ...mobileProps,
      maxLength: 10,
      keyboardType: "number-pad",
      returnKeyType: "done",
    };
  }

  return (
    <View>
      <TextInput
        style={[styles.inputStyle, inputStyle, { height }]}
        placeholderTextColor={theme.colors.lightBlack}
        {...mobileProps}
        {...remainingProps}
      />
      <InputError
        isError={isError}
        errorMsg={errorMsg}
        viewStyle={styles.inputError}
      />
      {children}
    </View>
  );
};

