import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import {
  NavigationContainerRef,
  ParamListBase,
  RouteProp,
  getFocusedRouteNameFromRoute,
  useNavigation,
} from "@react-navigation/native";
import React, { useRef } from "react";
import { TouchableOpacity } from "react-native";
import { bottomTabs } from "~/assets/constants";
import {
  addGreen,
  calendarTime,
  eventTwo,
  home,
  notificationTwo,
} from "~/assets/images";
import { ImageComponent } from "~/components/image-component";
import { ModalRefProps } from "~/components/modal-component";
import { ChatScreen } from "~/screens/chat";
import { CreatePostModal } from "~/screens/createEditPost/create-post-modal";
import { TabIcon } from "./TabIcon";
import { bottomNavigationVisibleScreens, navigations } from "./constant";
import { EventRoute } from "./event-route";
import { HomeRoute } from "./home-route";
import { MapRoute } from "./map-route";
import { createStyleSheet } from "./style";

const Tab = createBottomTabNavigator();
const header = () => null;
const NullComponent = () => <></>;

export const TabNavigator = () => {
  const { theme } = useAppTheme();
  const styles = createStyleSheet(theme);
  const modalRef: React.Ref<ModalRefProps> = useRef(null);
  const navigation = useNavigation();

  const bottomNav = [
    bottomTabs.home,
    bottomTabs.events,
    bottomTabs.map,
    bottomTabs.chat,
  ];

  const getTabData = (name: string) => {
    switch (name) {
      case bottomTabs.home:
        return {
          screenName: navigations.HOME_ROUTE,
          component: HomeRoute,
        };
      case bottomTabs.events:
        return {
          screenName: navigations.EVENT_ROUTE,
          component: EventRoute,
        };
      case bottomTabs.map:
        return {
          screenName: navigations.MAP_ROUTE,
          component: MapRoute,
        };
      case bottomTabs.chat:
        return {
          screenName: navigations.CHAT,
          component: ChatScreen,
        };
      default:
        return {
          screenName: "",
          component: HomeRoute,
        };
    }
  };

  let tabs = bottomNav?.map((nav) => getTabData(nav)) || [];

  tabs.splice(2, 0, {
    screenName: bottomTabs.addButton,
    component: NullComponent,
  });

  const renderAddButton = () => {
    return (
      <TouchableOpacity
        activeOpacity={0.8}
        onPress={() => modalRef.current?.onOpenModal()}
      >
        <ImageComponent source={addGreen} style={styles.addGreen} />
      </TouchableOpacity>
    );
  };

  const renderTabs = (
    route: RouteProp<ParamListBase, string>,
    focused: boolean
  ) => {
    if (route.name === navigations.HOME_ROUTE) {
      return (
        <TabIcon
          focused={focused}
          selectedImage={home}
          unSelectedImage={home}
        />
      );
    }
    if (route.name === navigations.EVENT_ROUTE) {
      return (
        <TabIcon
          focused={focused}
          selectedImage={calendarTime}
          unSelectedImage={calendarTime}
        />
      );
    }
    if (route.name === navigations.CHAT) {
      return (
        <TabIcon
          focused={focused}
          selectedImage={notificationTwo}
          unSelectedImage={notificationTwo}
        />
      );
    }
    if (route.name === navigations.MAP_ROUTE) {
      return (
        <TabIcon
          focused={focused}
          selectedImage={eventTwo}
          unSelectedImage={eventTwo}
        />
      );
    }
    return null;
  };

  const getTabbarStyle = (route: RouteProp<ParamListBase, string>) => {
    const routeName = getFocusedRouteNameFromRoute(route) ?? "";
    if (
      routeName.length === 0 ||
      (bottomNavigationVisibleScreens.includes(routeName) &&
        bottomNav.includes(routeName))
    ) {
      return [styles.container];
    }
    return [{ display: "none" }];
  };

  return (
    <>
      <Tab.Navigator
        screenOptions={({ route }) => ({
          tabBarIcon: ({ focused }) => renderTabs(route, focused),
          tabBarShowLabel: false,
        })}
        initialRouteName={navigations.HOME_ROUTE}
        backBehavior="none"
      >
        {tabs.map((tab) => {
          if (tab?.screenName === bottomTabs.addButton) {
            return (
              <>
                <Tab.Screen
                  name={tab?.screenName}
                  key={tab?.screenName}
                  component={tab?.component}
                  options={({ route }): any => ({
                    tabBarButton: renderAddButton,
                    tabBarStyle: getTabbarStyle(route),
                    header,
                  })}
                />
              </>
            );
          }
          return (
            <>
              <Tab.Screen
                name={tab?.screenName}
                key={tab?.screenName}
                component={tab?.component}
                options={({ route }): any => ({
                  header,
                  tabBarStyle: getTabbarStyle(route),
                })}
              />
            </>
          );
        })}
      </Tab.Navigator>
      <CreatePostModal
        navigation={
          navigation as unknown as NavigationContainerRef<ParamListBase>
        }
        modalRef={modalRef}
      />
    </>
  );
};

import axios, { AxiosInstance } from "axios";
import Toast from "react-native-simple-toast";
import { apiConstants } from "~/network/constant";
import { store } from "~/network/reducers/store";

export interface ErrorResponse {
  [key: string]: {
    status: number;
    data: {
      message: string;
      data: unknown;
      path: string;
    };
  };
}

export const axiosRequestConfig = {
  method: "get", // default
  timeout: 1000 * 10, // default is `0` (no timeout)

  // `withCredentials` indicates whether or not cross-site Access-Control requests
  // should be made using credentials
  withCredentials: false, // default

  // `maxContentLength` defines the max size of the http
  // response content in bytes allowed in node.js
  maxContentLength: 2000,

  // `maxBodyLength` (Node only option) defines the max size of the http
  // request content in bytes allowed
  maxBodyLength: 2000,

  // If set to 0, no redirects will be followed.
  maxRedirects: 0, // default
};

// Add a request interceptor
axios.interceptors.request.use(
  // Do something before request is sent
  (config) => config,
  // Do something with request error
  (error) => Promise.reject(error)
);

const interceptor = (ref: AxiosInstance) => {
  ref.interceptors.response.use(
    // Any status code that lie within the range of 2xx cause this function to trigger
    // Do something with response data
    (response) => response,
    async (error: ErrorResponse) => {
      const { status } = error?.response || {};

      // Any status codes that falls outside the range of 2xx cause this function to trigger
      // Do something with response error

      if (status === 401) {
        const user =
          (store.getState().userProfileReducer?.user as {
            refresh_token: string;
            access_token: string;
          }) || {};
        const res = await axios.post(
          `${process.env.API_URL}${apiConstants.refreshTokens}`,
          {
            refreshToken: user?.refresh_token,
          },
          {
            headers: {
              Authorization: `Bearer ${user?.access_token}`,
            },
          }
        );
        return;
      }

      if (status !== 200) {
        Toast.show(error?.response?.data?.message, Toast.LONG, {
          backgroundColor: "black",
        });
      }

      return Promise.reject(error?.response);
    }
  );
};

class APIService {
  userService!: AxiosInstance;

  homeService!: AxiosInstance;

  paymentService!: AxiosInstance;

  constructor() {
    this.initService();
  }

  async initService() {
    const userServiceUrl = process.env.API_URL;
    this.userService = axios.create({
      ...axiosRequestConfig,
      baseURL: userServiceUrl,
    });
    interceptor(this.userService);

    const homeServiceUrl = process.env.API_URL;
    this.homeService = axios.create({
      ...axiosRequestConfig,
      baseURL: homeServiceUrl,
    });
    interceptor(this.homeService);

    const paymentServiceUrl = process.env.STRIPE_BASE_URL;
    this.paymentService = axios.create({
      ...axiosRequestConfig,
      baseURL: paymentServiceUrl,
    });
    interceptor(this.paymentService);
  }
}

