  //     });
  //     response = getApiResponse(data);
  //   } catch (error: any) {
  //     response = getApiResponse(error);
  //   }

  //   return response;
  // };

  return {
    queryClient,
    queries,
    getEvent,
    createEvent,
    updateEvent,
    cancelEvent,
    getEvents,
    getRsvps,
    deleteRsvp,
    getTicketPriceBreakdown,
  };

