/* eslint-disable react-hooks/exhaustive-deps */
import { faCalendar } from "@fortawesome/free-regular-svg-icons";
import { faLocationDot } from "@fortawesome/free-solid-svg-icons";
import { FontAwesomeIcon } from "@fortawesome/react-native-fontawesome";
import { useNavigation } from "@react-navigation/native";
import { useMutation, useQuery } from "@tanstack/react-query";
import _ from "lodash/fp";
import { DateTime } from "luxon";
import React, { useState } from "react";
import { Controller, useFieldArray, useForm } from "react-hook-form";
import {
  Alert,
  Keyboard,
  Pressable,
  Text,
  TextInput,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from "react-native";
import { useAppTheme } from "~/app-hooks/use-app-theme";
import { useStringsAndLabels } from "~/app-hooks/use-strings-and-labels";
import { addGreen, edit } from "~/assets/images";
import { ButtonComponent } from "~/components/button-component";
import { ChooseDate } from "~/components/choose-date/ChooseDate";
import { ImageChooser } from "~/components/image-chooser/ImageChooser";
import { ImageComponent } from "~/components/image-component";
import { LocationAutocomplete } from "~/components/location-autocomplete/LocationAutocomplete";
import { useChapterFilter } from "~/navigation/AppContext";
import { useMyUserId } from "~/navigation/AuthContext";
import { EventMutations } from "~/network/api/services/useEventService";
import { useUserService } from "~/network/api/services/useUserService";
import { normalScale, verticalScale } from "~/theme/device/normalize";
import { ImageKey } from "~/types/image-info";
import {
  LocalEvent,
  LocalEventData,
  LocalEventUpdateData,
} from "~/types/local-event";
import { TicketTypeData } from "~/types/ticket-type-data";
import { FileKey } from "~/types/upload-file-data";
import { isNotEmpty, toCurrency } from "~/utils/common";
import { AddTicketModal } from "./AddTicketModal";
import { createStyleSheet } from "./style";

interface Callback {
  onSuccess: () => void;
}
interface EventEditorProps {
  event?: LocalEvent;
  isLoading: boolean;
  onSubmitCreate?: (data: LocalEventData, callback: Callback) => void;
  onSubmitUpdate?: (data: LocalEventUpdateData, callback: Callback) => void;
}
export const EventEditor = ({
  event,
  isLoading,
  onSubmitCreate,
  onSubmitUpdate,
}: EventEditorProps) => {
  const { theme } = useAppTheme();
  const { strings } = useStringsAndLabels();
  const viewCount = event?.viewCount;
  const styles = createStyleSheet(theme);
  const navigation = useNavigation();
  const [isEndDateActive, setEndDateActive] = useState(!!event?.endDate);
  const [curTicket, setCurTicket] = useState<number | undefined>();
  const myUserId = useMyUserId();
  const isMyEvent = myUserId === event?.host.id;
  const [isTicketModalVisible, setTicketModalVisible] = useState(false);
  const chapterFilter = useChapterFilter();

  const {
    queries: { me: getMe },
  } = useUserService();
  const { data: myProfile } = useQuery(getMe());

  const {
    control,
    getValues,
    setValue,
    handleSubmit,
    formState: { errors },
  } = useForm<LocalEventData>({
    defaultValues: event
      ? {
          ..._.omit(
            [
              "gratis",
              "replies",
              "postDate",
              "author",
              "host",
              "cancelDate",
              "viewCount",
            ],
            event
          ),
        }
      : {
          name: "",
          chapterId: chapterFilter?.id,
          startDate: DateTime.now().startOf("hour").plus({ hour: 1 }),
          coordinates: [],
          ticketTypes: [],
          images: [],
          timezone: DateTime.local().zoneName,
        },
  });

  const { append, remove } = useFieldArray({
    control,
    name: "ticketTypes",
  });

  const mutateCancelEvent = useMutation<LocalEvent, Error, string>({
    mutationKey: [EventMutations.cancelEvent],
  });

  const onSubmit = (data: LocalEventData | LocalEventUpdateData) => {
    const onSuccess = () => {
      navigation.goBack();
    };

    const createEvent = () =>
      onSubmitCreate!(
        {
          // ChapterId is overridden by chapterFilter set in defaultValues
          chapterId: myProfile?.homeChapter?.id,
          ..._.pickBy(isNotEmpty, data),
        } as LocalEventData,
        {
          onSuccess,
        }
      );

    if (
      !event &&
      chapterFilter?.id &&
      myProfile?.homeChapter?.id &&
      chapterFilter.id !== myProfile.homeChapter.id
    ) {
      Alert.alert(
        "Create outside of home chapter?",
        `This will create an event in ${chapterFilter.name} which is different from your home chapter. Are you sure you want to proceed?`,
        [
          { text: strings.no, onPress: () => null, style: "cancel" },
          {
            text: strings.yes,
            onPress: () => createEvent(),
          },
        ],
        { cancelable: false }
      );
    } else {
      event
        ? onSubmitUpdate!(_.pickBy(isNotEmpty, data) as LocalEventUpdateData, {
            onSuccess,
          })
        : createEvent();
    }
  };

  const handleTicketSelected = (index: number) => {
    setCurTicket(index);
    setTicketModalVisible(true);
  };

  const onTicketAdded = (ticket: TicketTypeData) => {
    append(ticket);
    setCurTicket(undefined);
    setTicketModalVisible(false);
  };

  const handleTicketRemoved = (index: number) => {
    remove(index);
  };

  const handleChangeImages = (images: ImageKey[]) => {
    setValue("images", images);
  };

  const ChooseStartAndEndDates = () => (
    <View style={styles.rowContainer}>
      <FontAwesomeIcon icon={faCalendar} size={20} />

      <Controller
        control={control}
        rules={{
          required: true,
        }}
        render={({ field: { onChange, value } }) => (
          <ChooseDate date={value} setDate={onChange}>
            <Text style={styles.label}>Start</Text>
          </ChooseDate>
        )}
        name="startDate"
      />
      {errors.startDate && <Text>This is required.</Text>}

      {isEndDateActive ? (
        <Controller
          control={control}
          render={({ field: { onChange, value } }) => (
            <ChooseDate
              date={value ?? getValues("startDate").plus({ hour: 1 })}
              setDate={onChange}
            >
              <Text style={styles.label}>End</Text>
            </ChooseDate>
          )}
          name="endDate"
        />
      ) : (
        <TouchableOpacity
          activeOpacity={0.3}
          onPress={() => {
            setEndDateActive(true);
          }}
          style={{
            paddingHorizontal: normalScale(4),
            paddingVertical: verticalScale(4),
          }}
        >
          <Text style={styles.label}>+ Add end date</Text>
        </TouchableOpacity>
      )}
    </View>
  );

  const verifyCancelEvent = (id: string) => {
    Alert.alert(
      strings.cancel,
      strings.verifyCancel,
      [
        { text: strings.no, onPress: () => null, style: "cancel" },
        {
          text: strings.yes,
          onPress: () => {
            mutateCancelEvent.mutate(id, {
              onSuccess: () => navigation.goBack(),
            });
          },
        },
      ],
      { cancelable: false }
    );
  };

  return (
    <View>
      <TouchableWithoutFeedback onPress={Keyboard.dismiss} accessible={false}>
        <View style={{ justifyContent: "space-between" }}>
          <View style={{ rowGap: 12 }}>
            <View>
              <Controller
                control={control}
                rules={{
                  required: true,
                }}
                render={({ field: { onChange, onBlur, value } }) => (
                  <TextInput
                    onChangeText={onChange}
                    onBlur={onBlur}
                    placeholder={strings.enterTitle}
                    style={styles.postInput}
                    value={value}
                  />
                )}
                name="name"
              />
              {errors.name && <Text>This is required.</Text>}
            </View>

            <ChooseStartAndEndDates />

            <View>
              <View style={styles.rowContainer}>
                <FontAwesomeIcon icon={faLocationDot} size={20} />
                <Controller
                  control={control}
                  rules={{
                    required: true,
                  }}
                  render={({ field: { onChange, value } }) => (
                    <LocationAutocomplete
                      address={value}
                      placeholder="Location"
                      onPress={(data, details) => {
                        onChange(data.description);
                        if (details) {
                          setValue("coordinates", [
                            details.geometry.location.lng,
                            details.geometry.location.lat,
                          ]);
                        }
                      }}
                    ></LocationAutocomplete>
                  )}
                  name="address"
                />
                {errors.address && <Text>This is required.</Text>}
              </View>
              <Controller
                control={control}
                render={({ field: { onChange, value } }) => (
                  <TextInput
                    placeholder={strings.enterVenue}
                    style={styles.postInput}
                    value={value}
                    onChangeText={onChange}
                  />
                )}
                name="venue"
              />
            </View>

            <View>
              <Controller
                control={control}
                rules={{
                  required: true,
                }}
                render={({ field: { onChange, value } }) => (
                  <TextInput
                    placeholder="Event details"
                    multiline
                    value={value}
                    style={[styles.postInput, { height: 100 }]}
                    onChangeText={onChange}
                  />
                )}
                name="details"
              />
              {errors.details && <Text>This is required.</Text>}
            </View>

            <ImageChooser
              id={event?.id}
              uploadKey={FileKey.createEventImage}
              defaultValue={getValues("images")}
              onChangeImages={handleChangeImages}
            />

            <View style={styles.rowContainer}>
              <Pressable onPress={() => setTicketModalVisible(true)}>
                <Text style={styles.label}>{strings.tickets}</Text>
                <ImageComponent source={addGreen} style={styles.addGreen} />
              </Pressable>
              <AddTicketModal
                isVisible={isTicketModalVisible}
                onSuccess={onTicketAdded}
                onDismiss={() => setTicketModalVisible(false)}
                value={
                  curTicket === undefined
                    ? undefined
                    : getValues("ticketTypes")[curTicket]
                }
              />
              <View>
                {getValues("ticketTypes").map((t, index) => {
                  return (
                    <View
                      key={`${t.quantity}${t.name}${t.price}`}
                      style={styles.rowContainer}
                    >
                      <Text style={styles.ticket}>{`${t?.name} - ${
                        t.quantity ? t.quantity : "Unlimited"
                      } ${
                        t.price === 0 ? "Free!" : toCurrency(t.price)
                      }`}</Text>
                      <View style={styles.rowContainer}>
                        <Pressable onPress={() => handleTicketSelected(index)}>
                          <ImageComponent source={edit} style={styles.edit} />
                        </Pressable>
                        <Pressable onPress={() => handleTicketRemoved(index)}>
                          <Text style={styles.delete}>X</Text>
                        </Pressable>
                      </View>
                    </View>
                  );
                })}
              </View>
            </View>
          </View>

          {event ? (
            <View>
              {isMyEvent ? (
                <View>
                  <View style={styles.uniqueViewCont}>
                    <Text style={styles.uniqueViewLbl}>Unique Views</Text>
                    <Text style={styles.uniqueCount}>{viewCount}</Text>
                  </View>
                  <View>
                    <TouchableOpacity
                      activeOpacity={0.8}
                      onPress={() => verifyCancelEvent(event.id)}
                      style={styles.cancelEventBtn}
                    >
                      <Text style={styles.cancelEventText}>
                        {strings.cancelEvent}
                      </Text>
                    </TouchableOpacity>
                  </View>
                </View>
              ) : null}
            </View>
          ) : null}
        </View>
      </TouchableWithoutFeedback>

      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-around",
          marginBottom: 12,
          marginTop: 30,
        }}
      >
        <ButtonComponent
          onPress={navigation.goBack}
          hasIcon={false}
          title="Cancel"
          style={styles.cancelButton}
        />

        <ButtonComponent
          onPress={handleSubmit(onSubmit)}
          title={event ? strings.updateEvent : strings.createEvent}
          disabled={isLoading}
          style={styles.postButton}
        />
      </View>
    </View>
  );
};

import AsyncStorage from "@react-native-async-storage/async-storage";
import {
  NavigationContainerRef,
  ParamListBase,
} from "@react-navigation/native";
import React, { forwardRef, useRef, useState } from "react";
import {
  FlatList,
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { launchImageLibrary } from "react-native-image-picker";
import { KeyboardAwareScrollView } from "react-native-keyboard-aware-scroll-view";
import Toast from "react-native-simple-toast";
import { useAppTheme } from "~/app-hooks/use-app-theme";
import { useStringsAndLabels } from "~/app-hooks/use-strings-and-labels";
import { buttonArrowGreen, saveIcon } from "~/assets/images";
import { ImageComponent } from "~/components/image-component";
import { ModalRefProps } from "~/components/modal-component";
import { createStyleSheet } from "./style";

interface AddPayoutExpenseScreenProps {
  navigation?: NavigationContainerRef<ParamListBase>;
  route?: {
    params: {
      id: string;
      addPayOutExpense: any;
    };
  };
}

export const AddPayoutExpenseScreen = (
  props: AddPayoutExpenseScreenProps,
  ref: React.Ref<unknown> | undefined
) => {
  const { theme } = useAppTheme();
  const { strings } = useStringsAndLabels();
  const { navigation, route } = props || {};
  const { id, addPayOutExpense } = route?.params ?? {};
  const styles = createStyleSheet(theme);
  // const { profilt, id, onSuccessFulData } = props || {};
  const addItemRef: React.Ref<ModalRefProps> = useRef(null);
  const [isLoading, LodingData] = useState(false);
  const [borderData, setBorderData] = useState("Expense");
  const [priceData, setPriceData] = useState(1);
  const [whoName, createPayoutWhoName] = useState("");
  const [amount, setAmount]: any = useState(0);
  const [descriptions, setDescriptions] = useState("");
  const [expenseArray, setExpenseArray]: any = useState([]);
  const [usertext, onUserSearch] = useState("");
  const [userList, recentlyJoinUser]: any = useState([]);
  const [usergratisList, userGratiesListData]: any = useState([]);
  const [userListArray, getUsetList]: any = useState();
  const [user_id, SetuserData] = useState({});
  const [imageSelectArray, setImageSelectArray]: any = useState([]);
  const [imageSelectArrayKey, setImageSelectArrayKey]: any = useState([]);
  const [newUserId, setNewUserIdData]: any = useState("");
  const [payoutListData, setPayoutListData]: any = useState([]);

  const expenseContClick = (item: any) => {
    setBorderData(item);
  };

  const priceClick = (item: any) => {
    setPriceData(item);
  };

  const resetState = () => {
    onUserSearch("");
    setDescriptions("");
    setAmount("");
    setImageSelectArray([]);
    setImageSelectArrayKey([]);
    SetuserData({});
    recentlyJoinUser([]);
  };

  const AddUserList = (item: any) => {
    const found = userList.find((element: any) => element.id == item.id);
    if (userList.length < 1) {
      if (!found) {
        recentlyJoinUser([...userList, item]);
        const newItems = { ...item };
        delete newItems.gratisNo;
        const newuserData = {
          ...newItems,
          first_name: item.first_name,
          last_name: item.last_name,
          pic: item.pic,
          id: item.id,
        };
        SetuserData(newuserData);
        getUsetList([newuserData]);
        setNewUserIdData(newuserData.id);
      } else {
        Toast.show("Already Added", Toast.LONG, {
          backgroundColor: "black",
        });
      }
      onUserSearch("");
    } else {
      Toast.show("You can not select more than one users", Toast.LONG, {
        backgroundColor: "black",
      });
    }
  };

  const removeSelectImage = (imageUrl: any) => {
    const newImage = imageSelectArray.filter(
      (person: any) => person.imageUrl !== imageUrl
    );
    setImageSelectArray(newImage);
  };

  async function createPayoutAPI() {
    LodingData(true);
    const token = await AsyncStorage.getItem("token");
    var getAmount = (addPayOutExpense * amount) / 100;
    if (priceData === 1) {
      var item: any = {
        user_id: newUserId,
        amount: parseInt(amount),
        description: descriptions,
        type: "price",
        images: imageSelectArrayKey,
        amount_percent: 0,
      };
    } else {
      var item: any = {
        user_id: newUserId,
        amount: getAmount,
        description: descriptions,
        type: "percentage",
        images: imageSelectArrayKey,
        amount_percent: parseInt(amount),
      };
    }

    try {
      const response = await fetch(
        process.env.API_URL +
          "/v3/events/event-financial/" +
          id +
          "/draft/payout",
        // process.env.API_URL + '/v3/events/event-financial/65d4c08f947463a3a650e663/draft/payout',
        {
          method: "post",
          headers: new Headers({
            Authorization: "Bearer " + token,
            "Content-Type": "application/json",
          }),
          body: JSON.stringify(item),
        }
      );

      const dataItem = await response.json();
      LodingData(false);
      if (dataItem.success) {
        // onSuccessFulData(dataItem.data);
        resetState();
        navigation?.goBack();
      } else {
        Toast.show(dataItem?.message, Toast.LONG, {
          backgroundColor: "black",
        });
      }
    } catch (error) {
      console.error(error);
      LodingData(false);
    }
  }

  const removeuserSelect = (id: any) => {
    const newPeople = userList.filter((person: any) => person !== id);
    recentlyJoinUser(newPeople);
  };

  async function gratisUserList(textUser: any) {
    const token = await AsyncStorage.getItem("token");
    var datas: any = {
      searchtext: textUser,
    };
    onUserSearch(textUser);
    LodingData(true);
    try {
      const response = await fetch(
        process.env.API_URL + "/v3/users/search-user?searchtext=" + textUser,
        {
          method: "get",
          headers: new Headers({
            Authorization: "Bearer " + token,
            "Content-Type": "application/x-www-form-urlencoded",
          }),
        }
      );
      const dataItem = await response.json();
      const result = dataItem?.data?.map((item: any) => {
        return { ...item };
      });
      userGratiesListData(result);
      LodingData(false);
    } catch (error) {
      LodingData(false);
      console.error(error);
    }
  }

  async function createExpenseAPI() {
    LodingData(true);
    const token = await AsyncStorage.getItem("token");
    var item: any = {
      user_id: newUserId,
      amount: parseInt(amount),
      description: descriptions,
      type: "price",
      images: imageSelectArrayKey,
    };
