interface Callback {
  onSuccess: () => void;
}
interface GroupEditorProps {
  group?: Group;
  myProfile: UserProfile;
  isLoading: boolean;
  onSubmitCreate?: (data: GroupData, callback: Callback) => void;
  onSubmitUpdate?: (data: GroupUpdateData, callback: Callback) => void;
}
export const GroupEditor = ({
  group,
  myProfile,
  isLoading,
  onSubmitCreate,
  onSubmitUpdate,
}: GroupEditorProps) => {
  const { theme } = useAppTheme();
  const styles = createStyleSheet(theme);
  const { strings } = useStringsAndLabels();
  const navigation = useNavigation();
  const { gotoChooseChapters, gotoChooseUsers } = useNavigations();
  const chapterFilter = useChapterFilter();

  const {
    control,
    setValue,
    getValues,
    watch,
    handleSubmit,
    formState: { errors },
  } = useForm<GroupUpdateData>({
    defaultValues: group
      ? {
          ..._.omit(["parentId"], group),
        }
      : {
          name: "",
          chapters: chapterFilter
            ? [{ id: chapterFilter.id, name: chapterFilter.name }]
            : [],
          summary: "",
          details: "",
          venue: "",
          address: "",
          coordinates: [],
          images: [],
          admins: [
            {
              id: myProfile.id,
              firstName: myProfile.firstName,
              lastName: myProfile.lastName,
              pic: myProfile.pic?.url,
            },
          ],
          members: [],
        },
  });

  const [admins, members, chapters] = watch(["admins", "members", "chapters"]);

  const { remove: removeAdmin } = useFieldArray({
    control,
    name: "admins",
  });

  const { remove: removeMember } = useFieldArray({
    control,
    name: "members",
  });

  const { remove: removeChapter } = useFieldArray({
    control,
    name: "chapters",
  });

  const { isPending: isUploadingImage } = useMutation<
    RemoteImage,
    Error,
    UploadFileData
  >({
    mutationKey: [UserMutations.uploadFile],
  });

  const handleRemoveAdmin = (user: OneUser) => {
    removeAdmin(admins!.findIndex((u) => u.id === user.id));
  };

  const handleRemoveMember = (user: OneUser) => {
    removeMember(members!.findIndex((u) => u.id === user.id));
  };

  const handleRemoveChapter = (chapter: ChapterData) => {
    removeChapter(members!.findIndex((c) => c.id === chapter.id));
  };

  React.useEffect(() => {
    const unsubscribe = navigation.addListener("state", (event) => {
      const params = event.data.state.routes.find(
        (r) =>
          r.name ===
          (Screens.SELECT_USERS as keyof ReactNavigation.RootParamList)
      )?.params as
        | RootStackScreenProps<Screens.SELECT_USERS>["route"]["params"]
        | undefined;

      if (params) {
        setValue(params.type as "admins" | "members", params.users);
      }
    });

    return unsubscribe;
  }, [navigation, setValue]);

  React.useEffect(() => {
    const unsubscribe = navigation.addListener("state", (event) => {
      const params = event.data.state.routes.find(
        (r) =>
          r.name ===
          (Screens.SELECT_CHAPTERS as keyof ReactNavigation.RootParamList)
      )?.params as
        | RootStackScreenProps<Screens.SELECT_CHAPTERS>["route"]["params"]
        | undefined;

      if (params) {
        setValue("chapters", params.chapters);
      }
    });

    return unsubscribe;
  }, [navigation, setValue]);

  const onSubmit = (data: GroupData | GroupUpdateData) => {
    const onSuccess = () => {
      navigation.goBack();
    };

    const removeUrls = (data: GroupData | GroupUpdateData) => ({
      // ChapterId is overridden by chapterFilter set in defaultValues
      chapters: [{ id: myProfile?.homeChapter?.id }],
      ..._.pickBy(isNotEmpty, data),
    });

    const clean = removeUrls(data);

    if (
      !group &&
      chapters &&
      chapters.length > 0 &&
      chapterFilter &&
      !chapters.find((c) => c.id === myProfile.homeChapter?.id)
    ) {
      Alert.alert(
        "Create outside of home chapter?",
        `This will create a group in ${chapterFilter.name} but not in your home chapter. Are you sure you want to proceed?`,
        [
          { text: strings.no, onPress: () => null, style: "cancel" },
          {
            text: strings.yes,
            onPress: () => onSubmitCreate!(clean as GroupData, { onSuccess }),
          },
        ],
        { cancelable: false }
      );
    } else {
      group
        ? onSubmitUpdate!(clean as GroupData as GroupUpdateData, {
            onSuccess,
          })
        : onSubmitCreate!(clean as GroupData, { onSuccess });
    }
  };

  const getButtonName = () => {
    return group ? strings.editGroup : strings.createGroup;
  };

  const handleChangeImages = (images: ImageKey[]) => {
    setValue("images", images);
  };

  return (
    <View>
      <Loader visible={isLoading || isUploadingImage} />
      <TouchableWithoutFeedback onPress={Keyboard.dismiss} accessible={false}>
        <View style={{ justifyContent: "space-between" }}>
          <View style={{ rowGap: 8 }}>
            <Text style={styles.emphasized}>
              {group ? strings.editGroup : strings.createGroup}
            </Text>
            <Controller
              control={control}
              rules={{
                required: true,
              }}
              render={({ field: { onChange, onBlur, value } }) => (
                <TextInput
                  placeholder="Name"
                  placeholderTextColor="#8B8888"
                  onBlur={onBlur}
                  value={value}
                  onChangeText={onChange}
                  style={styles.groupInput}
                  autoFocus={!group}
                ></TextInput>
              )}
              name="name"
            />
            {errors.name && <Text>This is required.</Text>}
            <Controller
              control={control}
              render={({ field: { onChange, onBlur, value } }) => (
                <TextInput
                  placeholder="Summary"
                  placeholderTextColor="#8B8888"
                  onBlur={onBlur}
                  value={value}
                  onChangeText={onChange}
                  style={styles.groupInput}
                  autoFocus={!!group}
                ></TextInput>
              )}
              name="summary"
            />

            <View style={styles.rowContainer}>
              <FontAwesomeIcon icon={faLocationDot} size={20} />
              <Controller
                control={control}
                render={({ field: { onChange, value } }) => (
                  <LocationAutocomplete
                    placeholder="Location"
                    address={value}
                    onPress={(data, details) => {
                      onChange(data.description);
                      if (details) {
                        setValue("coordinates", [
                          details.geometry.location.lng,
                          details.geometry.location.lat,
                        ]);
                      }
                    }}
                  />
                )}
                name="address"
              />
            </View>
            <Controller
              control={control}
              render={({ field: { onChange, onBlur, value } }) => (
                <TextInput
                  placeholder="Venue"
                  placeholderTextColor="#8B8888"
                  onBlur={onBlur}
                  value={value}
                  onChangeText={onChange}
                  style={styles.groupInput}
                  autoFocus={!!group}
                ></TextInput>
              )}
              name="venue"
            />

            <Controller
              control={control}
              render={({ field: { onChange, onBlur, value } }) => (
                <TextInput
                  multiline
                  placeholder="Details"
                  placeholderTextColor="darkgray"
                  textAlignVertical={"top"}
                  value={value}
                  onBlur={onBlur}
                  onChangeText={onChange}
                  style={styles.groupInputBody}
                ></TextInput>
              )}
              name="details"
            />
          </View>

          <View
            style={{
              flexDirection: "row",
              marginTop: 20,
            }}
          >
            <Text style={styles.emphasized}>{strings.chapters}</Text>
            <Pressable
              onPress={() =>
                gotoChooseChapters({
                  chapters: group?.chapters ?? chapters!,
                })
              }
            >
              <FontAwesomeIcon icon={faPlus} size={20} />
            </Pressable>
          </View>
          <ChapterListHorizontal
            chapters={chapters as ChapterData[]}
            onRemoveChapter={handleRemoveChapter}
          />

          <View
            style={{
              flexDirection: "row",
              marginTop: 20,
            }}
          >
            <Text style={styles.emphasized}>{strings.admins}</Text>
            <Pressable
              onPress={() =>
                gotoChooseUsers({
                  type: "admins",
                  users: group?.admins ?? admins!,
                })
              }
            >
              <FontAwesomeIcon icon={faPlus} size={20} />
            </Pressable>
          </View>
          <UserListHorizontal
            users={(admins as OneUser[]) ?? []}
            onRemoveUser={
              // Don't allow removing user if there is only one admin
              admins?.length && admins.length > 1
                ? handleRemoveAdmin
                : undefined
            }
          />
          <View
            style={{
              flexDirection: "row",
              marginTop: 20,
            }}
          >
            <Text style={styles.emphasized}>{strings.members}</Text>
            <Pressable
              onPress={() =>
                gotoChooseUsers({
                  type: "members",
                  users: group?.members ?? members!,
                })
              }
            >
              <FontAwesomeIcon icon={faPlus} size={20} />
            </Pressable>
          </View>
          <UserListHorizontal
            users={(members as OneUser[]) ?? []}
            onRemoveUser={handleRemoveMember}
          />

          <Text style={styles.emphasized}>{strings.images}</Text>
          <ImageChooser
            id={group?.id}
            uploadKey={FileKey.groupImage}
            defaultValue={getValues("images")}
            onChangeImages={handleChangeImages}
          />

          <View
            style={{
              flexDirection: "row",
              justifyContent: "space-around",
              bottom: 0,
              marginBottom: 0,
              marginTop: 30,
            }}
          >
            <ButtonComponent
              onPress={navigation.goBack}
              hasIcon={false}
              title="Cancel"
              style={styles.cancelButton}
            />
            <ButtonComponent
              onPress={handleSubmit(onSubmit)}
              icon={buttonArrowGreen}
              title={getButtonName()}
              style={styles.groupButton}
              disabled={isLoading}
            />
          </View>
        </View>
      </TouchableWithoutFeedback>
    </View>
  );
};

import { useMutation, useQuery } from "@tanstack/react-query";
import React, { useState } from "react";
