  PostMutations,
  ReportPostParams,
} from "~/network/api/services/usePostService";
import { Report } from "~/types/report";
import { createStyleSheet } from "./style";

export const ReportContent = ({
  navigation,
  route,
}: RootStackScreenProps<Screens.REPORT_CONTENT_MODAL>) => {
  const postId = route.params.postId;
  const { theme } = useAppTheme();
  const styles = createStyleSheet(theme);

  const [reportReason, setReportReason] = useState<string>();

  const { mutate } = useMutation<Report, Error, ReportPostParams>({
    mutationKey: [PostMutations.reportPost],
  });

  const submitReportReason = () => {
    if (!reportReason) {
      Toast.show("Add Reason", Toast.LONG, {
        backgroundColor: "black",
      });
    } else {
      mutate(
        {
          postId,
          reason: reportReason,
        },
        {
          onSuccess: () => {
            navigation.goBack();
            Toast.show("Report Submit successfully", Toast.LONG, {
              backgroundColor: "black",
            });
          },
        }
      );
    }
  };

  return (
    <ShortModal height={200}>
      <Text style={styles.gratiesTitle}>Report Content</Text>
      <View>
        <TextInput
          onChangeText={(text) => setReportReason(text)}
          style={styles.replyInput}
          placeholder="Add Reason"
        ></TextInput>
      </View>
      <TouchableOpacity
        onPress={() => submitReportReason()}
        activeOpacity={0.8}
        style={styles.purchaseContainer}
      >
        <View />
        <Text style={styles.titleTwo}>Submit</Text>
        <View>
          <ImageComponent
            source={buttonArrowGreen}
            style={styles.buttonArrow}
          />
        </View>
      </TouchableOpacity>
    </ShortModal>
  );
};

import {
  AppleRequestResponse,
  appleAuth,
} from "@invertase/react-native-apple-authentication";
import {
  GoogleSignin,
  User,
  statusCodes,
} from "@react-native-google-signin/google-signin";
import { useMutation } from "@tanstack/react-query";
