export const SignUpScreen = () => {
  const { strings } = useStringsAndLabels();
  const { handleSignUp, handleSignInUnverified } =
    useContext(AuthDispatchContext);

  const EMAIL_REGEX =
    /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|.(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/g;
  const PASSWORD_REGEX = /^(?=.*[a-zA-Z])(?=.*\d)[a-zA-Z\d\w\W]{8,}$/;

  const { mutate: signUp, isPending } = useMutation<
    CurrentUser,
    Error,
    NewUser
  >({
    mutationKey: [AuthMutations.signUp],
  });

  const {
    control,
    handleSubmit,
    getValues,
    setValue,
    formState: { errors },
  } = useForm<NewUser>({
    defaultValues: {
      firstName: "",
      lastName: "",
      email: "",
      password: "",
      confirmPassword: "",
    },
  });

  const onSignUp = (data: NewUser) => {
    signUp(_.pickBy(isNotEmpty, data) as unknown as NewUser, {
      onSuccess: (user) => {
        handleSignUp(user);
        Alert.alert(
          "Registration success!",
          "Please check your email to verify your account.",
          [
            {
              text: "OK",
              onPress: () =>
                handleSignInUnverified({
                  email: getValues("email"),
                  password: getValues("password"),
                }),
            },
          ]
        );
      },
    });
  };

  const keyboardDismiss = () => {
    Keyboard.dismiss();
  };

  return (
    <TouchableOpacity activeOpacity={1} onPress={keyboardDismiss}>
      <SizedBox height={verticalScale(22)} />
      <KeyboardAwareScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollView}
      >
        <View style={styles.container}>
          <Text style={styles.texClass}>{strings.email}</Text>
          <Controller
            control={control}
            rules={{
              required: true,
              pattern: EMAIL_REGEX,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                placeholderTextColor="#8B8888"
                style={styles.textInput}
                autoCapitalize="none"
                autoComplete="email"
                autoCorrect={false}
                inputMode="email"
                keyboardType="email-address"
                onChangeText={onChange}
                onBlur={onBlur}
                value={value}
              />
            )}
            name="email"
          />
          {errors.email && (
            <Text>
              {errors.email.type === "required"
                ? "This is required."
                : "Must be an email"}
            </Text>
          )}

          <SizedBox height={verticalScale(10)} />
          <Text style={styles.texClass}>{strings.password}</Text>
          <Controller
            control={control}
            rules={{
              required: true,
              minLength: 8,
              pattern: PASSWORD_REGEX,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                secureTextEntry
                placeholderTextColor="#8B8888"
                style={styles.textInput}
                autoCapitalize="none"
                autoComplete="new-password"
                inputMode="text"
                onChangeText={onChange}
                onBlur={onBlur}
                value={value}
              />
            )}
            name="password"
          />
          {errors.password && (
            <Text>
              {errors.password.type === "required"
                ? "This is required."
                : errors.password.type === "minLength"
                ? "Must be at least 8 characters"
                : "Must contain at least one letter and one number"}
            </Text>
          )}

          <SizedBox height={verticalScale(10)} />
          <Text style={styles.texClass}>{strings.confirmPassword}</Text>
          <Controller
            control={control}
            rules={{
              required: true,
              validate: (value, formValues) => value === formValues.password,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                secureTextEntry
                placeholderTextColor="#8B8888"
                style={styles.textInput}
                autoCapitalize="none"
                autoComplete="new-password"
                inputMode="text"
                onChangeText={onChange}
                onBlur={onBlur}
                value={value}
              />
            )}
            name="confirmPassword"
          />
          {errors.confirmPassword && <Text>Must match password</Text>}
          <SizedBox height={verticalScale(10)} />
          <Text style={styles.texClass}>{strings.firstName}</Text>
          <Controller
            control={control}
            rules={{
              required: true,
              minLength: 2,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                placeholderTextColor="#8B8888"
                style={styles.textInput}
                onChangeText={onChange}
                onBlur={onBlur}
                value={value}
              />
            )}
            name="firstName"
          />
          {errors.firstName && <Text>This is required</Text>}

          <SizedBox height={verticalScale(14)} />
          <Text style={styles.texClass}>{strings.lastName}</Text>
          <Controller
            control={control}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                placeholderTextColor="#8B8888"
                style={styles.textInput}
                onChangeText={onChange}
                onBlur={onBlur}
                value={value}
              />
            )}
            name="lastName"
          />
          <SizedBox height={verticalScale(14)} />

          <ButtonComponent
            style={styles.signUpBtn}
            onPress={handleSubmit(onSignUp)}
            title={strings.signUpTwo}
            disabled={isPending}
          />
        </View>
      </KeyboardAwareScrollView>
    </TouchableOpacity>
  );
};

