import { UserProfile, UserProfileUpdateData } from "~/types/user-profile";
import { removeEmptyFields } from "~/utils/common";
import { createStyleSheet } from "./style";

interface Callback {
  onSuccess: () => void;
}
interface ProfileEditorProps {
  userProfile: UserProfile;
  saveProfile: (data: UserProfileUpdateData, callback?: Callback) => void;
}
export const ProfileEditor = ({
  userProfile,
  saveProfile,
}: ProfileEditorProps) => {
  const { theme } = useAppTheme();
  const { strings } = useStringsAndLabels();
  const styles = createStyleSheet(theme);
  const [allSkills, setSkills] = useState(userProfile.skills);
  const [skillValue, setSkillValue] = useState("");

  const {
    control,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<UserProfileUpdateData>({
    defaultValues: {
      firstName: "",
      lastName: "",
      nickname: "",
      catchphrase: "",
      about: "",
      skills: [],
      ..._.omit(["gratis", "joinDate", "pic", "homeProfile"], userProfile),
    },
  });

  const handleRemoveSkill = (id: string) => {
    const newPeople = allSkills.filter((person) => person !== id);

    setSkills(newPeople);
  };

  const onAddSkill = (text: string) => {
    const foundSkill = allSkills.find((data: string) => data == text);
    if (!foundSkill) {
      if (text !== "" && text !== undefined) {
        setSkills([...allSkills, text]);
        setSkillValue("");
      }
      setValue("skills", [...allSkills, text]);
    } else {
      Toast.show("Already Added", Toast.LONG, {
        backgroundColor: "black",
      });
    }
  };

  const renderSkill: ListRenderItem<string> = ({ item }) => (
    <Pill
      onPressPill={() => handleRemoveSkill(item)}
      pillStyle={styles.marginBottom}
      key={item}
      label={item}
    />
  );

  const onSubmit = (data: UserProfileUpdateData) => {
    saveProfile(removeEmptyFields(data) as UserProfileUpdateData, {
      onSuccess: () => {
        Toast.show("Profile saved", Toast.SHORT, {
          backgroundColor: "black",
        });
      },
    });
  };

  return (
    <View style={{ marginTop: -90 }}>
      <View style={styles.center}>
        <View style={styles.userNameClass}>
          <Controller
            control={control}
            rules={{
              required: true,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                onChangeText={onChange}
                value={value}
                onBlur={onBlur}
                placeholder={strings.firstName}
                placeholderTextColor="#818181"
                style={styles.firstName}
              />
            )}
            name="firstName"
          />
          {errors.firstName && <Text>This is required.</Text>}

          <Controller
            control={control}
            rules={{
              required: true,
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                onChangeText={onChange}
                value={value}
                onBlur={onBlur}
                placeholder={strings.lastName}
                placeholderTextColor="#818181"
                style={styles.lastName}
              />
            )}
            name="lastName"
          />
        </View>
        {errors.lastName && <Text>This is required.</Text>}

        <View style={styles.circularView}>
          <Controller
            control={control}
            render={({ field: { onChange, onBlur, value } }) => (
              <TextInput
                onChangeText={onChange}
                value={value}
                onBlur={onBlur}
                placeholder="enter nickname"
                placeholderTextColor="#818181"
                style={styles.des}
              />
            )}
            name="nickname"
          />
        </View>
      </View>

      <View style={styles.gratiesCont}>
        <View style={styles.payoutAndGratisCont}>
          <Image
            source={gratis}
            resizeMode="cover"
            style={styles.gratiesImage}
          ></Image>
          <Text style={styles.gratiesNumber}>{userProfile.gratis}</Text>
        </View>
      </View>

      <View style={styles.aboutView}>
        <Controller
          control={control}
          render={({ field: { onChange, onBlur, value } }) => (
            <Input
              inputStyle={styles.input}
              onChangeText={onChange}
              value={value}
              onBlur={onBlur}
              placeholderTextColor="#818181"
              placeholder="enter a catchphrase"
              multiline
            />
          )}
          name="catchphrase"
        />

        <Text style={styles.membership}>{strings.aboutMe}</Text>
        <Controller
          control={control}
          render={({ field: { onChange, onBlur, value } }) => (
            <Input
              onChangeText={onChange}
              value={value}
              onBlur={onBlur}
              inputStyle={styles.input}
              placeholder="tell us about yourself!"
              placeholderTextColor="#818181"
              multiline
            />
          )}
          name="about"
        />

        <Text style={styles.membership}>{strings.skills}</Text>
        {skillValue !== "" ? (
          <TouchableOpacity
            style={{ zIndex: 1111111 }}
            onPress={() => {
              onAddSkill(skillValue);
            }}
          >
            <ImageComponent
              style={styles.skillAddImage}
              source={addGreen}
            ></ImageComponent>
          </TouchableOpacity>
        ) : (
          <View></View>
        )}

        <View style={styles.skillCont}>
          <Input
            inputStyle={styles.input}
            // onSubmitEditing={onAddSkill}
            placeholder={strings.addSkill}
            value={skillValue}
            onChangeText={setSkillValue}
            placeholderTextColor="#818181"
            children
          />
        </View>

        <View style={styles.row}>
          <FlatListComponent
            data={allSkills}
            keyExtractor={(item) => item.toString()}
            renderItem={renderSkill}
            numColumns={100}
            showsHorizontalScrollIndicator={false}
            columnWrapperStyle={styles.flexWrap}
          />
        </View>
        <ButtonComponent
          title={strings.save}
          onPress={handleSubmit(onSubmit)}
        />
      </View>
    </View>
  );
};

import { useMutation, useQueries, useQueryClient } from "@tanstack/react-query";
import _ from "lodash/fp";
import React, { useState } from "react";
import { TouchableOpacity } from "react-native";
import { useAppTheme } from "~/app-hooks/use-app-theme";
import { useStringsAndLabels } from "~/app-hooks/use-strings-and-labels";
import {
  Actionsheet,
  ActionsheetBackdrop,
  ActionsheetContent,
  ActionsheetDragIndicator,
  ActionsheetDragIndicatorWrapper,
} from "~/components/ui/actionsheet";
import { Box } from "~/components/ui/box";
import { Button, ButtonSpinner, ButtonText } from "~/components/ui/button";
import { Card } from "~/components/ui/card";
import { Heading } from "~/components/ui/heading";
import { HStack } from "~/components/ui/hstack";
import { Text } from "~/components/ui/text";
import { VStack } from "~/components/ui/vstack";
import {
  SubscriptionMutations,
  useSubscriptionService,
} from "~/network/api/services/useSubscriptionService";
import { StripePaymentInfo } from "~/types/stripe-payment-info";
import { StripeCheckout } from "../event-detail/StripeCheckout";

interface SubscriptionPlansProps {
  onClose: () => void;
}
export const SubscriptionPlans = ({ onClose }: SubscriptionPlansProps) => {
  const { theme } = useAppTheme();
  const { strings } = useStringsAndLabels();
  const [isMonthlySelected, setMonthlySelected] = useState(false);
  const [isYearlySelected, setYearlySelected] = useState(false);
  const [isCheckoutVisible, setCheckoutVisible] = useState(false);
  const [paymentInfo, setPaymentInfo] = useState<StripePaymentInfo>();
  const queryClient = useQueryClient();

  const {
    queries,
    queries: { plans: listPlans, subscriptions: listSubscriptions },
  } = useSubscriptionService();
  const { plans, subscriptions } = useQueries({
    queries: [listPlans(), listSubscriptions()],
    combine: (results) => ({
      plans: results[0].data,
      subscriptions: results[1].data,
    }),
  });

  const hostPlan = plans?.find((p) => p.metadata.type === "host");

  const monthlyPlan = hostPlan?.prices.find(
    (p) => p.recurring.interval === "month"
  );
  const yearlyPlan = hostPlan?.prices.find(
    (p) => p.recurring.interval === "year"
  );
  const selectedPlan = isMonthlySelected
    ? monthlyPlan
    : isYearlySelected
    ? yearlyPlan
    : undefined;

  const { mutate: subscribe, isPending: isSubscribePending } = useMutation<
    StripePaymentInfo,
    Error,
    string
  >({
    mutationKey: [SubscriptionMutations.subscribe],
  });

  const toggleMonthlyPlan = () => {
    const isSelected = isMonthlySelected;
    setMonthlySelected(!isSelected);
    if (!isSelected) {
      setYearlySelected(false);
    }
  };

  const toggleYearlyPlan = () => {
    const isSelected = isYearlySelected;
    setYearlySelected(!isSelected);
    if (!isSelected) {
      setMonthlySelected(false);
    }
  };

  const createSubscription = () => {
    // TODO Use isSuccess field rather than callback function so that
    // invalidate can be done in hook
    void subscribe(selectedPlan!.id, {
      onSuccess(data) {
        setPaymentInfo(data);
        setCheckoutVisible(true);
      },
    });
  };

  const closeCheckout = () => setCheckoutVisible(false);

  const handleCheckoutComplete = () => {
    closeCheckout();
    onClose();

    void queryClient.invalidateQueries({
      queryKey: queries.subscriptions().queryKey,
    });
  };

  const isPurchasable = () =>
    _.isEmpty(subscriptions) && (isMonthlySelected || isYearlySelected);

  return (
    <>
      <Actionsheet defaultIsOpen={true} onClose={onClose} snapPoints={[45]}>
        <ActionsheetBackdrop />
        <ActionsheetContent>
          <ActionsheetDragIndicatorWrapper>
            <ActionsheetDragIndicator />
          </ActionsheetDragIndicatorWrapper>
          {hostPlan && (
            <>
              <Heading className="mt-4 text-center" size="2xl">
                {`${hostPlan.name} ${strings.membership}`}
              </Heading>

              <VStack>
                <HStack className="my-4 gap-4">
                  {monthlyPlan && (
                    <Card variant={isMonthlySelected ? "filled" : "outline"}>
                      <TouchableOpacity
                        activeOpacity={0.8}
                        //   style={[
                        //     styles.selectView,
                        //     me?.billingInterval === "monthly" &&
                        //       styles.selectedSelectView,
                        //   ]}
                        onPress={toggleMonthlyPlan}
                      >
                        <Heading size="4xl">
                          ${Math.round(monthlyPlan.unit_amount / 100)}
                        </Heading>

                        <Text className="text-center">{`per ${monthlyPlan.recurring.interval}`}</Text>
                      </TouchableOpacity>
                    </Card>
                  )}

                  {yearlyPlan && (
                    <Card variant={isYearlySelected ? "filled" : "outline"}>
                      <TouchableOpacity
                        activeOpacity={0.8}
                        //   style={[
                        //     styles.selectView,
                        //     me?.billingInterval === "yearly" &&
                        //       styles.selectedSelectView,
                        //   ]}
                        onPress={toggleYearlyPlan}
                      >
                        <Heading size="4xl">
                          ${Math.round(yearlyPlan.unit_amount / 100)}
                        </Heading>

                        <Text className="text-center">{`per ${yearlyPlan.recurring.interval}`}</Text>
                      </TouchableOpacity>
                    </Card>
                  )}
                </HStack>

                <Button
                  isDisabled={!isPurchasable()}
                  onPress={createSubscription}
                >
                  {isSubscribePending && <ButtonSpinner />}
                  <ButtonText>{strings.purchase}</ButtonText>
                </Button>
              </VStack>
            </>
          )}
        </ActionsheetContent>
      </Actionsheet>
      {paymentInfo && (
        <StripeCheckout
          paymentInfo={paymentInfo}
          isOpen={isCheckoutVisible}
          onCancel={closeCheckout}
          onCheckoutComplete={handleCheckoutComplete}
        >
          <Box className="m-6">
            <Text>{`You will be charged $${
              selectedPlan!.unit_amount / 100
            } per ${selectedPlan?.recurring.interval}.`}</Text>
          </Box>
        </StripeCheckout>
      )}
    </>
  );
};

