export const removeEmptyFields = (data: any) =>
  // eslint-disable-next-line @typescript-eslint/no-unsafe-return
  _.mapValues((v) => (v === "" ? undefined : v), data);

export const isNotEmpty = _.overEvery([
  _.negate(_.isUndefined),
  _.negate(_.isEmpty),
]);

export const findChapter = (chapterId?: string, chapters?: Chapter[]) =>
  chapters?.find((c) => c.id === chapterId);

import { launchImageLibrary } from "react-native-image-picker";

const postImageUploadAPI = async (fileItem: any, base64Item: any) => {
  const token = await AsyncStorage.getItem("token");
  const pic: any = {
    uploadKey: "createPostImg",
    imageName: fileItem,
    base64String: "data:image/jpeg;base64," + base64Item,
  };

  LOG.debug("> postImageUploadAPI");
  try {
    onLoading?.(true);

    const response = await fetch(
      process.env.API_URL + "/v3/users/upload/file",
      {
        method: "post",
        headers: new Headers({
          Authorization: "Bearer " + token,
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(pic),
      }
    );
    const data = (await response.json())?.data;
    LOG.debug("< postImageUploadAPI", data);
    if (data) {
      setImages([...images, data]);
    }
    notifyImagesChanged();
    onLoading?.(true);
  } catch (error) {
    LOG.error("postImageUploadAPI", error);
    onLoading?.(false);
  }
};

